package com.technova.model;
import jakarta.persistence.*; import java.math.BigDecimal;
@Entity @Table(name="detalle_compra") public class DetalleCompra { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) @Column(name="id_detalle_compra") private Long id; @Column(name="id_compra") private Long compraId; @Column(name="id_producto") private Long productoId; private Integer cantidad; @Column(name="precio_unitario") private BigDecimal precioUnitario; private BigDecimal importe; public DetalleCompra(){} public Long getId(){return id;} public void setId(Long v){id=v;} public Long getCompraId(){return compraId;} public void setCompraId(Long v){compraId=v;} public Long getProductoId(){return productoId;} public void setProductoId(Long v){productoId=v;} public Integer getCantidad(){return cantidad;} public void setCantidad(Integer v){cantidad=v;} public BigDecimal getPrecioUnitario(){return precioUnitario;} public void setPrecioUnitario(BigDecimal v){precioUnitario=v;} public BigDecimal getImporte(){return importe;} public void setImporte(BigDecimal v){importe=v;} }
